"""RoboPaint 春: camera calibrated brush strokes. All motion recorded in actions/*.npz."""
import sys, json, time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output');r=Robot()
Q=np.array([-3.987430829965888e-7,1.,-3.555323928594589e-7,-2.8657268558163196e-8])
SURFACE=.0202

def obs(name='obs'):
 o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)
 o.save('/app/runs/'+name)
 for c,a in o.last.items():Image.fromarray(a).save('/app/runs/'+name+'/'+c+'.png')
 return o

def execute(P,name='move',cams=['practice_cam'],fps=10):
 P=np.asarray(P);d=ROOT/'actions';d.mkdir(exist_ok=True)
 for i in range(0,len(P),180):
  a=P[i:i+180]; k=len(list(d.glob('*.npz')));np.savez(d/f'{k:04d}.npz',poses=a,dt=.05,name=name)
  res=r.submit('ee_pose',a,dt=.05,cameras=cams,video='frames',video_fps=fps,note=name)
  res.save(f'/app/runs/action{k:04d}')
  for c,img in res.last.items():Image.fromarray(img).save(f'/app/runs/action{k:04d}/{c}.png')
  print(name,k,'steps',res.meta.get('control_steps'),'now',res.group('tcp_pose',now=True)[:3], 'plan',res.meta.get('plan'),flush=True)
  if res.stopped or res.done:raise RuntimeError(res.meta)
 return res

def move(xyz,speed=.06,hold=.25,name='move'):
 o=r.get_obs(cameras=[]);start=o.group('tcp_pose',now=True)[:3];xyz=np.array(xyz)
 n=max(2,int(np.ceil(np.linalg.norm(xyz-start)/speed/.05)))
 P=[[*v,*Q] for v in np.linspace(start,xyz,n+1)[1:]]+[[*xyz,*Q]]*int(hold/.05)
 return execute(P,name)

def dip():
 move([-.1,.185,.075],name='to ink');move([-.1,.185,.018],speed=.025,hold=.5,name='dip');move([-.1,.185,.07],name='lift ink')

def park():return move([-.30,.20,.12],name='park')

if __name__=='__main__':
 if sys.argv[1]=='position':
  move([-.1,.185,.09],name='view ink');obs('inkview')
 elif sys.argv[1]=='dip':dip();park();obs('dipped')
