S=[np.array(a,float) for a in STROKES];N=512
T=np.array(Image.open('/app/target.png').resize((N,N)))[:,:,0]<100
D=distance_transform_edt(~T);W=1.25+.75*(D>2.25)
def render(a):
 im=Image.new('L',(N,N));d=ImageDraw.Draw(im)
 for x,y,w in sample(a,spacing=2):
  x/=2;y/=2;w/=2;d.ellipse((x-w/2,y-w/2,x+w/2,y+w/2),fill=1)
 return np.array(im,dtype=bool)
M=[render(a) for a in S]
def loss(m):return np.count_nonzero(T&~m)+np.sum(W[m&~T])
print('start',loss(np.any(M,axis=0)),flush=True)
for step in [4,3,2,1]:
 for k in [3,4,6,0,1,2,5,7,8]:
  other=np.any(M[:k]+M[k+1:],axis=0);best=loss(M[k]|other)
