m=np.any(M,axis=0);print('IoU',np.sum(m&T)/np.sum(m|T),'farstray',np.sum(m&(D>2.25))/np.sum(T),flush=True)
o=np.ones((N,N,3),np.uint8)*245;o[T]=[70,130,230];o[m]=[200,50,50];o[m&T]=[20,20,20];Image.fromarray(o).resize((1024,1024)).save('/app/output/optimized.png')
